import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"docs/guide/installation.md","filePath":"guide/installation.md"}'),n={name:"docs/guide/installation.md"};function o(r,e,l,c,d,h){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>The development build uses a user-local bundle loaded by kitty. No root privileges, shell framework, Node.js runtime, or network image service belongs in the extension’s normal runtime path. JPEG/GIF normalization invokes the existing system Python launcher only to impose OS limits before starting ImageMagick; it does not install Python packages.</p><div class="warning custom-block"><p class="custom-block-title">Experimental local artifact</p><p>There is no public download or published package yet. The local release candidate is <code>kittyscape-0.1.0.dev1.tar.gz</code>. Full platform qualification remains in progress; use the <a href="./../reference/compatibility.html">compatibility matrix</a> to see the remaining gates.</p></div><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Read the exact <a href="./../reference/compatibility.html">compatibility matrix</a>. Test an isolated kitty instance before enabling a daily-use configuration. See <a href="./uninstall.html">uninstall and rollback</a> before applying any setup change.</p><p>The helper checks kitty 0.38.1 or newer and the watcher, timer, image, and directory APIs before changing files. This is a capability check, not a platform support claim.</p><h2 id="one-step-install" tabindex="-1">One-step install <a class="header-anchor" href="#one-step-install" aria-label="Permalink to &quot;One-step install&quot;">​</a></h2><p>From the extracted bundle directory, run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kitty</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./setup.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>The command applies the owned loader files, creates <code>~/.config/kittyscape/kittyscape.json</code> when it does not exist, and opens a new kitty OS window with the watcher loaded. No kitty restart is required.</p><p>The loader is installed into kitty’s active configuration directory, usually <code>~/.config/kitty</code>. Your directory rules are separate and live in the Kittyscape configuration directory. The helper never overwrites or removes the rules file, including during uninstall.</p><p>Use <code>--preview</code> to inspect changes without writing files. Use <code>--kitty-config-dir /path/to/kitty</code> for a non-default kitty configuration and <code>--config-dir /path/to/kittyscape</code> for a different rules location. <code>--no-launch</code> installs only, which is useful for automation.</p><p>The helper rejects kitty configuration paths containing a newline, NUL, or dollar sign, because those paths cannot be represented safely in its include. It also rejects a dangling <code>kitty.conf</code> symlink or a hard-linked <code>kitty.conf</code>. Resolve the reported condition without replacing unrelated user data.</p><h2 id="extract-and-configure" tabindex="-1">Extract and configure <a class="header-anchor" href="#extract-and-configure" aria-label="Permalink to &quot;Extract and configure&quot;">​</a></h2><p>The local build produces the archive, a manifest, and <code>SHA256SUMS</code> in the repository’s <code>dist/</code> directory. Compare the archive’s SHA-256 digest with <code>SHA256SUMS</code> before extracting it. On Linux, use <code>sha256sum</code>; on macOS, use <code>shasum -a 256</code>. The <a href="/evidence/release.json">release record</a> identifies the artifact, executed checks, and open gates.</p><p>From the directory containing the archive:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -xzf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kittyscape-0.1.0.dev1.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kittyscape-0.1.0.dev1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kitty</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./setup.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>These commands work in Bash, Zsh, and Fish. The helper runs in kitty’s embedded Python through <code>+launch</code>; it does not require a system Python installation.</p><p>Immediately edit the created rules file with the <a href="./getting-started.html">getting-started example</a>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$EDITOR </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/.config/kittyscape/kittyscape.json</span></span></code></pre></div><p>Save it, then use <strong>Ctrl+Shift+F9</strong> in the fresh window to reload the rules. The fresh window starts at your home directory and has a known baseline before the first image change. Repeating a valid installation is idempotent: it does not append another include block or replace an existing rules file.</p><p>Check <strong>Ctrl+Shift+F6</strong> for status, then follow the image-switching and restoration checks in <a href="./getting-started.html#check-the-result">getting started</a>. The generated <a href="./../reference/actions.html">lifecycle bindings</a> use Ctrl+Shift+F6 through Ctrl+Shift+F10. Review any existing bindings on those keys before using a personal configuration.</p><p>Finish the evaluation with <a href="./uninstall.html">restore, removal, and rollback</a>. A file-level installation check does not prove graphical restoration or qualify another platform.</p><h2 id="existing-windows" tabindex="-1">Existing windows <a class="header-anchor" href="#existing-windows" aria-label="Permalink to &quot;Existing windows&quot;">​</a></h2><p>The installer does not restart kitty or modify an existing OS window’s image. Kitty loads watcher changes only for newly created windows, and an already open window has no trustworthy original background for Kittyscape to restore. The installer therefore opens a fresh configured OS window immediately. Keep using your current windows normally; move work into the new window when you want directory backgrounds.</p><h2 id="what-the-helper-owns" tabindex="-1">What the helper owns <a class="header-anchor" href="#what-the-helper-owns" aria-label="Permalink to &quot;What the helper owns&quot;">​</a></h2><p>All runtime paths below are relative to the selected kitty configuration directory.</p><table tabindex="0"><thead><tr><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>kittyscape/0.1.0.dev1/</code></td><td>Versioned runtime and setup bundle.</td></tr><tr><td><code>kittyscape/0.1.0.dev1/kittyscape/location.json</code></td><td>Absolute path to the user-owned rules file.</td></tr><tr><td><code>kittyscape.conf</code></td><td>Watcher entry and lifecycle key mappings.</td></tr><tr><td>Marked block in <code>kitty.conf</code></td><td>One include for <code>kittyscape.conf</code>.</td></tr><tr><td><code>kittyscape/kitty.conf.backup</code></td><td>Original configuration snapshot for verified rollback.</td></tr><tr><td><code>kittyscape/install-receipt.json</code></td><td>Ownership and integrity information.</td></tr></tbody></table><p>Existing symlinked <code>kitty.conf</code> files and included files retain their relationships. The helper checks owned-file hashes before replacement or removal. It preserves later unrelated configuration edits during uninstall.</p><h2 id="manual-installation" tabindex="-1">Manual installation <a class="header-anchor" href="#manual-installation" aria-label="Permalink to &quot;Manual installation&quot;">​</a></h2><p>The helper is optional. For manual setup, use an empty destination, keep a backup and a written inventory of your changes, and copy the extracted bundle into <code>kittyscape/0.1.0.dev1/</code> beneath the selected configuration root. Do not overwrite an existing directory.</p><p>Create <code>kittyscape/location.json</code> <strong>inside the copied bundle</strong>, with the selected absolute JSON path. Its full location is <code>kittyscape/0.1.0.dev1/kittyscape/location.json</code> beneath the configuration root:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;config&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/home/you/.config/kittyscape/kittyscape.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>Create a separate include file containing the watcher entry and whichever lifecycle mappings you want. For the example directory above:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>watcher /tmp/kittyscape trial/kittyscape/0.1.0.dev1/kittyscape/watcher.py</span></span>
<span class="line"><span>map ctrl+shift+f6 kitten &#39;/tmp/kittyscape trial/kittyscape/0.1.0.dev1/kittyscape/action.py&#39; status</span></span>
<span class="line"><span>map ctrl+shift+f7 kitten &#39;/tmp/kittyscape trial/kittyscape/0.1.0.dev1/kittyscape/action.py&#39; pause</span></span>
<span class="line"><span>map ctrl+shift+f8 kitten &#39;/tmp/kittyscape trial/kittyscape/0.1.0.dev1/kittyscape/action.py&#39; resume</span></span>
<span class="line"><span>map ctrl+shift+f9 kitten &#39;/tmp/kittyscape trial/kittyscape/0.1.0.dev1/kittyscape/action.py&#39; reload</span></span>
<span class="line"><span>map ctrl+shift+f10 kitten &#39;/tmp/kittyscape trial/kittyscape/0.1.0.dev1/kittyscape/action.py&#39; restore</span></span></code></pre></div><p>Add one <code>include /absolute/path/to/your/include.conf</code> line to the intended kitty configuration. Keep your <code>kittyscape.json</code> and images separate from runtime files. Follow the <a href="#existing-windows">existing-windows requirement</a>, then run the same isolated checks.</p><p>A manual installation has no helper ownership receipt. Follow the <a href="./uninstall.html#manual-removal">manual removal instructions</a> using your recorded inventory.</p><h2 id="updates-and-recovery" tabindex="-1">Updates and recovery <a class="header-anchor" href="#updates-and-recovery" aria-label="Permalink to &quot;Updates and recovery&quot;">​</a></h2><p>Keep the previous local bundle and valid configuration until the new artifact passes its checks. Use the shipped rollback path if installation cannot be verified. The <a href="./../releases.html">release notes</a> record compatibility changes; an unqualified upgrade must not inherit the previous version’s support label.</p>`,39)])])}const k=t(n,[["render",o]]);export{u as __pageData,k as default};
